  /* ==========================================================================
     3. MORPHING & MATH HELPERS
     ========================================================================== */
  function interpolateCubics(pairs, progress) {
    const inv = 1 - progress;
    const p0 = pairs[0];
    const startX = (p0[0][0] * inv + p0[1][0] * progress).toFixed(2);
    const startY = (p0[0][1] * inv + p0[1][1] * progress).toFixed(2);
    let d = 'M ' + startX + ',' + startY;

    for (let i = 0; i < pairs.length; i++) {
      const [p1, p2] = pairs[i];
      const c0x = (p1[2] * inv + p2[2] * progress).toFixed(2);
      const c0y = (p1[3] * inv + p2[3] * progress).toFixed(2);
      const c1x = (p1[4] * inv + p2[4] * progress).toFixed(2);
      const c1y = (p1[5] * inv + p2[5] * progress).toFixed(2);
      const a1x = (p1[6] * inv + p2[6] * progress).toFixed(2);
      const a1y = (p1[7] * inv + p2[7] * progress).toFixed(2);
      d += ' C ' + c0x + ',' + c0y + ' ' + c1x + ',' + c1y + ' ' + a1x + ',' + a1y;
    }
    return d + ' Z';
  }

  function easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  // Material 3 Expressive Sinusoidal Wave Generators
  function generateWavyPathString(width, height, wavelength, amplitude, phase = 0, activeWidth = null) {
    const centerY = height / 2;
    const endX = (activeWidth !== null) ? Math.min(width, Math.max(0, activeWidth)) : width;
    if (endX <= 0) return 'M 0 ' + centerY + ' L 0 ' + centerY;

    const step = 2.5;
    let d = 'M 0 ' + (centerY + amplitude * Math.sin(-phase)).toFixed(2);

    for (let x = step; x <= endX; x += step) {
      let curAmp = amplitude;
      if (activeWidth !== null && x > endX - wavelength / 2) {
        const t = (endX - x) / (wavelength / 2);
        curAmp = amplitude * Math.sin(Math.max(0, t) * Math.PI / 2);
      }
      const y = centerY + curAmp * Math.sin((2 * Math.PI * x / wavelength) - phase);
      d += ' L ' + x.toFixed(1) + ' ' + y.toFixed(2);
    }
    return d;
  }

  function generateDeterminateTrackPath(width, height, wavelength, amplitude, phase, activeWidth) {
    const centerY = height / 2;
    const startX = Math.max(0, Math.min(width, activeWidth));
    return 'M ' + startX.toFixed(1) + ' ' + centerY + ' L ' + width.toFixed(1) + ' ' + centerY;
  }

  function generateWavySegmentPath(width, height, wavelength, amplitude, phase, centerProgress, windowRatio = 0.45) {
    const centerY = height / 2;
    const totalTravel = width * (1 + windowRatio * 2);
    const centerX = centerProgress * totalTravel - (width * windowRatio);
    const halfWindow = (width * windowRatio) / 2;
    const startX = Math.max(0, centerX - halfWindow);
    const endX = Math.min(width, centerX + halfWindow);

    if (endX <= startX) return 'M 0 ' + centerY + ' L 0 ' + centerY;

    const step = 2.5;
    let firstPoint = true;
    let d = '';

    for (let x = startX; x <= endX; x += step) {
      const distFromCenter = Math.abs(x - centerX) / halfWindow;
      const envelope = Math.cos(Math.min(1, distFromCenter) * Math.PI / 2);
      const curAmp = amplitude * envelope;
      const y = centerY + curAmp * Math.sin((2 * Math.PI * x / wavelength) - phase);

      if (firstPoint) {
        d = 'M ' + x.toFixed(1) + ' ' + y.toFixed(2);
        firstPoint = false;
      } else {
        d += ' L ' + x.toFixed(1) + ' ' + y.toFixed(2);
      }
    }
    return d || ('M 0 ' + centerY + ' L 0 ' + centerY);
  }

  // Material 3 Expressive Circular Wavy Path Generator
  // Supports continuous closed loops, dynamic sub-arcs with start and end angles,
  // traveling sinusoidal phase, and authentic Material 3 amplitude tapering at rounded tips.
  function generateCircularWavyPath(cx, cy, baseRadius, amplitude, waves, phase = 0, startAngle = -Math.PI / 2, endAngle = null, taperStart = true, taperEnd = true) {
    if (endAngle === null) {
      endAngle = startAngle + 2 * Math.PI;
    }
    const span = endAngle - startAngle;
    if (span <= 0.001) {
      return 'M ' + (cx + baseRadius * Math.cos(startAngle)).toFixed(2) + ' ' + (cy + baseRadius * Math.sin(startAngle)).toFixed(2);
    }

    const isFullClosed = span >= (2 * Math.PI - 0.005);
    const rampSpan = Math.min(span * 0.25, (2 * Math.PI) / (waves * 2));
    const stepCount = Math.max(36, Math.ceil((span / (2 * Math.PI)) * waves * 36));

    let d = '';
    for (let i = 0; i <= stepCount; i++) {
      const t = i / stepCount;
      const theta = startAngle + t * span;

      let curAmp = amplitude;
      if (!isFullClosed) {
        if (taperStart && theta < startAngle + rampSpan) {
          const u = (theta - startAngle) / rampSpan;
          curAmp = amplitude * Math.sin(Math.max(0, u) * Math.PI / 2);
        }
        if (taperEnd && theta > endAngle - rampSpan) {
          const u = (endAngle - theta) / rampSpan;
          curAmp = amplitude * Math.sin(Math.max(0, u) * Math.PI / 2);
        }
      }

      const r = baseRadius + curAmp * Math.sin(waves * theta + phase);
      const x = (cx + r * Math.cos(theta)).toFixed(2);
      const y = (cy + r * Math.sin(theta)).toFixed(2);

      if (i === 0) {
        d = 'M ' + x + ' ' + y;
      } else {
        d += ' L ' + x + ' ' + y;
      }
    }

    if (isFullClosed) {
      d += ' Z';
    }
    return d || ('M ' + cx + ' ' + cy);
  }

  // Material 3 Clean Circular Arc Generator (for Smooth Track option)
  function generateCircularArcPath(cx, cy, radius, startAngle, endAngle) {
    const span = endAngle - startAngle;
    if (span <= 0.001) {
      return 'M ' + (cx + radius * Math.cos(startAngle)).toFixed(2) + ' ' + (cy + radius * Math.sin(startAngle)).toFixed(2);
    }
    if (span >= (2 * Math.PI - 0.005)) {
      return 'M ' + (cx + radius).toFixed(2) + ' ' + cy.toFixed(2) +
             ' A ' + radius.toFixed(2) + ' ' + radius.toFixed(2) + ' 0 1 0 ' + (cx - radius).toFixed(2) + ' ' + cy.toFixed(2) +
             ' A ' + radius.toFixed(2) + ' ' + radius.toFixed(2) + ' 0 1 0 ' + (cx + radius).toFixed(2) + ' ' + cy.toFixed(2) + ' Z';
    }
    const x1 = (cx + radius * Math.cos(startAngle)).toFixed(2);
    const y1 = (cy + radius * Math.sin(startAngle)).toFixed(2);
    const x2 = (cx + radius * Math.cos(endAngle)).toFixed(2);
    const y2 = (cy + radius * Math.sin(endAngle)).toFixed(2);
    const largeArc = span > Math.PI ? 1 : 0;
    return 'M ' + x1 + ' ' + y1 + ' A ' + radius.toFixed(2) + ' ' + radius.toFixed(2) + ' 0 ' + largeArc + ' 1 ' + x2 + ' ' + y2;
  }

  function interpolateHexColor(color1, color2, factor) {
    const r1 = parseInt(color1.slice(1, 3), 16);
    const g1 = parseInt(color1.slice(3, 5), 16);
    const b1 = parseInt(color1.slice(5, 7), 16);
    const r2 = parseInt(color2.slice(1, 3), 16);
    const g2 = parseInt(color2.slice(3, 5), 16);
    const b2 = parseInt(color2.slice(5, 7), 16);
    const r = Math.round(r1 + factor * (r2 - r1));
    const g = Math.round(g1 + factor * (g2 - g1));
    const b = Math.round(b1 + factor * (b2 - b1));
    return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
  }

